import {
  CodexOAuthConnectorId,
  CodexOAuthInstallationId,
  CodexOAuthProfileId,
  CodexOAuthSubject,
} from "@bundjil/codex-oauth";
import {
  Config,
  ConfigProvider,
  Context,
  Effect,
  Layer,
  Option,
  Redacted,
  Schema,
} from "effect";

import { CodexProxyRouteError } from "./errors.js";
import {
  CodexProxyDevServerConfig,
  CodexProxyMode,
  CodexProxyRuntimeConfig,
} from "./schemas.js";
import type {
  CodexProxyDevServerConfig as CodexProxyDevServerConfigType,
  CodexProxyRuntimeConfig as CodexProxyRuntimeConfigType,
} from "./schemas.js";

const proxyModeConfig = Config.schema(
  CodexProxyMode,
  "BUNDJIL_CODEX_PROXY_MODE"
).pipe(Config.withDefault("mock"));

const internalTokenConfig = Config.redacted(
  "BUNDJIL_CODEX_PROXY_INTERNAL_TOKEN"
);

const profileIdConfig = Config.schema(
  CodexOAuthProfileId,
  "BUNDJIL_CODEX_PROFILE_ID"
).pipe(Config.withDefault("default"));

const connectorIdConfig = Config.schema(
  CodexOAuthConnectorId,
  "BUNDJIL_CODEX_CONNECTOR_ID"
).pipe(Config.withDefault("bundjil-codex-proxy"));

const installationIdConfig = Config.schema(
  CodexOAuthInstallationId,
  "BUNDJIL_CODEX_INSTALLATION_ID"
).pipe(Config.withDefault("local"));

const subjectPrincipalIdConfig = Config.schema(
  Schema.NonEmptyString,
  "BUNDJIL_CODEX_SUBJECT_ID"
).pipe(Config.withDefault("default"));

const accountIdConfig = Config.option(
  Config.schema(Schema.NonEmptyString, "BUNDJIL_CODEX_ACCOUNT_ID")
);

const portConfig = Config.port("PORT").pipe(Config.withDefault(8787));

const SchemaDecode = {
  codexOAuthSubject: (input: unknown) =>
    CodexOAuthSubject.pipe(Schema.decodeUnknownEffect)(input).pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            boundary: "CodexProxyRuntimeConfig",
            cause,
            code: "bad_request",
            message: "Unable to decode Codex proxy OAuth subject config.",
            responseMessage: "The Codex proxy config is invalid.",
            status: 400,
          })
      )
    ),
  codexProxyDevServerConfig: (input: unknown) =>
    CodexProxyDevServerConfig.pipe(Schema.decodeUnknownEffect)(input).pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            boundary: "CodexProxyRuntimeConfig",
            cause,
            code: "bad_request",
            message: "Unable to decode Codex proxy dev server config.",
            responseMessage: "The Codex proxy config is invalid.",
            status: 400,
          })
      )
    ),
  codexProxyRuntimeConfig: (input: unknown) =>
    CodexProxyRuntimeConfig.pipe(Schema.decodeUnknownEffect)(input).pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            boundary: "CodexProxyRuntimeConfig",
            cause,
            code: "bad_request",
            message: "Unable to decode Codex proxy runtime config.",
            responseMessage: "The Codex proxy config is invalid.",
            status: 400,
          })
      )
    ),
} as const;

export class CodexProxyConfig extends Context.Service<
  CodexProxyConfig,
  CodexProxyRuntimeConfigType
>()("@bundjil/codex-proxy/CodexProxyConfig") {}

export const loadCodexProxyConfig = Effect.gen(
  function* loadCodexProxyConfigFromProvider() {
    const mode = yield* proxyModeConfig;
    const internalToken = yield* internalTokenConfig;
    const profileId = yield* profileIdConfig;
    const connectorId = yield* connectorIdConfig;
    const installationId = yield* installationIdConfig;
    const subjectPrincipalId = yield* subjectPrincipalIdConfig;
    const accountId = yield* accountIdConfig;
    const subject = yield* SchemaDecode.codexOAuthSubject({
      connectorId,
      installationId,
      principal: {
        id: subjectPrincipalId,
        issuer: "https://auth.openai.com",
        type: "chatgpt-user",
      },
      profileId,
      provider: "codex",
    });

    return yield* SchemaDecode.codexProxyRuntimeConfig({
      mode,
      internalToken: Redacted.value(internalToken),
      subject,
      ...(Option.isNone(accountId) ? {} : { accountId: accountId.value }),
    });
  }
).pipe(Effect.withSpan("CodexProxyConfig.load"));

export const loadCodexProxyConfigFromEnv = loadCodexProxyConfig.pipe(
  Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
);

export const loadCodexProxyDevServerConfig = Effect.gen(
  function* loadCodexProxyDevServerConfigFromProvider() {
    const port = yield* portConfig;

    return yield* SchemaDecode.codexProxyDevServerConfig({ port });
  }
).pipe(Effect.withSpan("CodexProxyDevServerConfig.load"));

export const loadCodexProxyDevServerConfigFromEnv =
  loadCodexProxyDevServerConfig.pipe(
    Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv()))
  );

export const CodexProxyConfigLive = Layer.effect(
  CodexProxyConfig,
  loadCodexProxyConfig
).pipe(Layer.provide(ConfigProvider.layer(ConfigProvider.fromEnv())));

export const CodexProxyConfigLayer = (config: CodexProxyRuntimeConfigType) =>
  Layer.succeed(CodexProxyConfig, config);

export const makeCodexProxyConfig = (input: unknown) =>
  SchemaDecode.codexProxyRuntimeConfig(input);

export type { CodexProxyDevServerConfigType, CodexProxyRuntimeConfigType };
import {
  OpenAICompatibleChatCompletionRequest,
  OpenAICompatibleProxy,
  OpenAICompatibleProxyInput,
} from "@bundjil/codex-oauth";
import { Effect, Layer, Redacted, Schema } from "effect";
import type { HttpServerRequest } from "effect/unstable/http";
import { HttpRouter, HttpServerResponse } from "effect/unstable/http";

import { CodexProxyConfig, CodexProxyConfigLive } from "./env.js";
import { CodexProxyRouteError } from "./errors.js";
import { CodexProxyOpenAICompatibleProxyMockLive } from "./mock.layer.js";
import {
  CodexProxyErrorResponse,
  CodexProxyHealthResponse,
} from "./schemas.js";
import type { CodexProxyErrorCode } from "./schemas.js";

const healthJson = HttpServerResponse.schemaJson(CodexProxyHealthResponse);
const errorJson = HttpServerResponse.schemaJson(CodexProxyErrorResponse);

const errorResponse = (
  code: CodexProxyErrorCode,
  message: string,
  status: number
) =>
  errorJson(
    {
      error: {
        code,
        message,
      },
    },
    { status }
  ).pipe(Effect.orDie);

const healthRoute = Effect.gen(function* healthRoute() {
  const config = yield* CodexProxyConfig;

  return yield* healthJson({
    mode: config.mode,
    ok: true,
    service: "bundjil-codex-proxy",
  }).pipe(Effect.orDie);
});

const chatCompletionsRoute = (request: HttpServerRequest.HttpServerRequest) =>
  Effect.gen(function* chatCompletionsRoute() {
    const config = yield* CodexProxyConfig;

    if (config.mode === "live") {
      return yield* new CodexProxyRouteError({
        code: "live_mode_unavailable",
        message:
          "Live Codex proxy mode is not enabled in this implementation slice.",
        responseMessage: "Live Codex proxy mode is not available yet.",
        status: 503,
      });
    }

    const body = yield* request.text.pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            cause,
            code: "bad_request",
            message: "Unable to read Codex proxy request body.",
            responseMessage: "The request body could not be read.",
            status: 400,
          })
      )
    );
    const completion = yield* Schema.decodeUnknownEffect(
      Schema.fromJsonString(OpenAICompatibleChatCompletionRequest)
    )(body).pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            boundary: "OpenAICompatibleChatCompletionRequest",
            cause,
            code: "bad_request",
            message:
              "Unable to decode OpenAI-compatible chat completion request.",
            responseMessage:
              "The request does not match the Codex proxy contract.",
            status: 400,
          })
      )
    );
    const proxyInput = yield* Schema.decodeUnknownEffect(
      OpenAICompatibleProxyInput
    )({
      ...(request.headers["authorization"] === undefined
        ? {}
        : { authorization: request.headers["authorization"] }),
      completion: {
        ...(config.accountId === undefined
          ? {}
          : { accountId: config.accountId }),
        request: completion,
        subject: config.subject,
      },
      internalToken: Redacted.value(config.internalToken),
    }).pipe(
      Effect.mapError(
        (cause) =>
          new CodexProxyRouteError({
            boundary: "OpenAICompatibleProxyInput",
            cause,
            code: "bad_request",
            message: "Unable to decode Codex proxy request envelope.",
            responseMessage:
              "The request does not match the Codex proxy contract.",
            status: 400,
          })
      )
    );
    const proxy = yield* OpenAICompatibleProxy;
    const stream = yield* proxy.handleChatCompletions(proxyInput);

    return HttpServerResponse.raw(stream.body, {
      contentType: stream.contentType,
      headers: {
        "cache-control": "no-cache, no-transform",
        "x-accel-buffering": "no",
        "x-bundjil-codex-proxy-mode": config.mode,
      },
      status: 200,
    });
  }).pipe(
    Effect.catchTags({
      CodexProxyRouteError: (error) =>
        errorResponse(error.code, error.responseMessage, error.status),
      OpenAICompatibleProxyAuthError: () =>
        errorResponse("unauthorized", "Unauthorized.", 401),
      CodexResponsesRequestError: () =>
        errorResponse("proxy_error", "The proxy request failed.", 502),
      CodexHttpNetworkError: () =>
        errorResponse("proxy_error", "The proxy request failed.", 502),
      CodexHttpStatusError: () =>
        errorResponse("proxy_error", "The proxy request failed.", 502),
      CodexResponsesStreamError: () =>
        errorResponse("proxy_error", "The proxy stream failed.", 502),
      OAuthProfileNotFound: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      OAuthProfileSchemaError: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      OAuthProfileStorageError: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      CodexOAuthTokenMissing: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      CodexOAuthTokenExpired: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      CodexOAuthTokenProviderError: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
      CodexOAuthUnsupportedRuntimePath: () =>
        errorResponse("proxy_error", "Codex auth is not available.", 502),
    })
  );

const notFoundRoute = errorResponse("not_found", "Not found.", 404);

export const CodexProxyRoutesLive = Layer.effectDiscard(
  Effect.gen(function* registerCodexProxyRoutes() {
    const router = yield* HttpRouter.HttpRouter;

    yield* router.add("GET", "/health", healthRoute);
    yield* router.add("POST", "/v1/chat/completions", chatCompletionsRoute);
    yield* router.add("*", "/*", notFoundRoute);
  })
);

export const makeCodexProxyAppLayer = (configLayer = CodexProxyConfigLive) =>
  Layer.mergeAll(
    configLayer,
    CodexProxyOpenAICompatibleProxyMockLive,
    CodexProxyRoutesLive
  );

export const CodexProxyAppLive = makeCodexProxyAppLayer();

export const makeCodexProxyWebHandler = (appLayer = CodexProxyAppLive) =>
  HttpRouter.toWebHandler(appLayer, {
    disableLogger: true,
  });

export const codexProxyWebHandler = makeCodexProxyWebHandler();
import { codexProxyWebHandler } from "./server.js";

export {
  CodexProxyAppLive,
  CodexProxyRoutesLive,
  codexProxyWebHandler,
  makeCodexProxyAppLayer,
  makeCodexProxyWebHandler,
} from "./server.js";
export {
  CodexProxyConfig,
  CodexProxyConfigLayer,
  CodexProxyConfigLive,
  loadCodexProxyConfig,
  loadCodexProxyConfigFromEnv,
  loadCodexProxyDevServerConfig,
  loadCodexProxyDevServerConfigFromEnv,
  makeCodexProxyConfig,
} from "./env.js";
export {
  CodexProxyDevServerConfig,
  CodexProxyErrorResponse,
  CodexProxyHealthResponse,
  CodexProxyMode,
  CodexProxyRuntimeConfig,
