        token: Redacted.value(config.restToken),
        automaticDeserialization: false,
        enableTelemetry: false,
      }),
      config
    );
  }).pipe(Effect.withSpan("UpstashKeyValueStoreLive"))
).pipe(Layer.provide(ConfigProvider.layer(ConfigProvider.fromEnv())));

